      showModal(`<div class="dashboard-head"><div class="detail-eyebrow">OWNER HOUSEHOLD TOOLS</div><h2 id="modalTitle">${escapeHTML(title)}</h2><p>Invite a verified renter by account email. They must accept before viewing shared bills.</p></div><div class="inbox-list">${members}</div><form class="inquiry-form" id="householdInviteForm"><label>Renter account email<input name="email" type="email" required autocomplete="email"/></label><button class="search-button">Send household invitation <span>→</span></button></form><button class="text-button" id="openHouseholdBills">Open private bill ledger →</button>`);
      $("#householdInviteForm").onsubmit=async(event)=>{event.preventDefault();const email=new FormData(event.currentTarget).get("email");try{const result=await api(`/api/owner/listings/${encodeURIComponent(listingId)}/household`,{method:"POST",body:JSON.stringify({email})});toast(result.message);ownerHousehold(listingId,title);}catch(error){toast(error.message);}};
      document.querySelectorAll("[data-remove-household-member]").forEach((button)=>button.onclick=async()=>{if(!confirm("Remove this person's household access?"))return;try{await api(`/api/owner/listings/${encodeURIComponent(listingId)}/household`,{method:"POST",body:JSON.stringify({action:"remove",memberId:Number(button.dataset.removeHouseholdMember)})});ownerHousehold(listingId,title);}catch(error){toast(error.message);}});
